tool_input.command:
cat > /tmp/find.py <<'EOF'
import ast, sys

targets = {
 "src/attr/_funcs.py": [421,489],
 "src/attr/_make.py": [474,475,498,499,552,855,887,1046,1198,1205,1216,2094,2558,2648,2656,2690],
}

for path, lines in targets.items():
    tree = ast.parse(open(path).read())
    # build stack
    res = {}
    def walk(node, stack):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                walk(child, stack + [child.name])
            else:
                walk(child, stack)
        if isinstance(node, ast.Name) and node.id == "_OBJ_SETATTR":
            res.setdefault(node.lineno, ".".join(stack))
    walk(tree, [])
    for ln in lines:
        print(path, ln, res.get(ln, "!!NOT FOUND (string/other)"))
EOF
